#include <stdio.h>
#include <string.h>
#include <ctype.h>

int main(int argc, char *argv[]) {
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }
    const char *s1 = argv[1];
    const char *s2 = argv[2];
    if (strlen(s1) >= 0x401 || strlen(s2) >= 0x401) { // 1025 characters limit
        puts("TOO_LONG");
        return 0;
    }
    int cnt1[256] = {0};
    int cnt2[256] = {0};
    for (const char *p = s1; *p; ++p) {
        if (*p == ' ') continue; // ignore spaces
        if (isalpha((unsigned char)*p)) {
            unsigned char c = (unsigned char)tolower((unsigned char)*p);
            cnt1[c]++;
        }
    }
    for (const char *p = s2; *p; ++p) {
        if (*p == ' ') continue; // ignore spaces
        if (isalpha((unsigned char)*p)) {
            unsigned char c = (unsigned char)tolower((unsigned char)*p);
            cnt2[c]++;
        }
    }
    int anagram = 1;
    for (int i = 0; i < 256; ++i) {
        if (cnt1[i] != cnt2[i]) {
            anagram = 0;
            break;
        }
    }
    puts(anagram ? "ANAGRAM" : "NOT_ANAGRAM");
    return 0;
}
